"""Individually inspected scientific roles; these are interpretations, not execution claims."""
PATTERNS={
 'skat':r'(?<![A-Za-z0-9_])SKAT(?![- ]?O)(?![A-Za-z0-9_])',
 'skato':r'(?<![A-Za-z0-9_])SKAT[- ]?O(?![A-Za-z0-9_])',
 'acat':r'(?<![A-Za-z0-9_])ACAT(?:[- ]?[OV])?(?![A-Za-z0-9_])'}

def role(pid,tool,indices,context,summary,scope,provider=None,version=None,links=None):
    return dict(paper_id=pid,tool_id=tool,paragraphs=indices,usage_context=context,
                usage_summary=summary,implementation_scope_note=scope,provider=provider,
                reported_tool_edition=version,linked_details=links or {})

def provider(name,index,pattern,edition=None):
    return dict(name=name,paragraph_index=index,pattern=pattern,edition=edition)

